def schema_drift(expected, actual):
    drift = set()

    def add_leaf_paths(obj, path):
        if isinstance(obj, dict):
            for key, value in obj.items():
                child = f"{path}.{key}" if path else key
                add_leaf_paths(value, child)
        else:
            drift.add(path)

    def compare(exp, act, path):
        for key in exp:
            child = f"{path}.{key}" if path else key
            if key not in act:
                add_leaf_paths(exp[key], child)
            else:
                exp_val = exp[key]
                act_val = act[key]
                if isinstance(exp_val, dict) and isinstance(act_val, dict):
                    compare(exp_val, act_val, child)
                elif isinstance(exp_val, dict) or isinstance(act_val, dict):
                    drift.add(child)
                elif exp_val != act_val:
                    drift.add(child)

        for key in act:
            if key not in exp:
                child = f"{path}.{key}" if path else key
                add_leaf_paths(act[key], child)

    compare(expected, actual, "")
    return sorted(drift)

