def merge_payload_ranges(items):
    for start, end, payload in items:
        if start > end:
            raise ValueError("start > end")

    if not items:
        return []

    ordered = sorted(items, key=lambda x: (x[0], x[1]))

    result = []
    cur_start, cur_end, cur_payload = ordered[0]

    for start, end, payload in ordered[1:]:
        if payload == cur_payload and start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            result.append([cur_start, cur_end, cur_payload])
            cur_start, cur_end, cur_payload = start, end, payload

    result.append([cur_start, cur_end, cur_payload])
    return result
